#!/bin/bash
# Generated by scripts/build-raycast-launchers.mjs; edit launchers/config.json.
# @raycast.schemaVersion 1
# @raycast.title DockFlow: Zen
# @raycast.mode silent
# @raycast.packageName DockFlow Presets
# @raycast.icon 🧰
# @raycast.description Apply the existing Zen DockFlow preset.

set -euo pipefail
cli='/Applications/DockFlow.app/Contents/MacOS/DockFlowCLI'
if [[ ! -x "$cli" ]]; then
  printf 'DockFlow CLI is missing: %s\n' "$cli" >&2
  exit 1
fi
exec "$cli" apply --name 'Zen' --skip-if-active
